#!/usr/bin/env python3
"""CI-only dense F1/report gate. No large file is generated by unit tests."""
import json
import os
from pathlib import Path
import shutil
import signal
import subprocess
import tempfile
from dense_rss_workload import CYCLE_BYTES, TIMELINE_LIMIT, write_workload, write_steady_workload, warnings_for


def measure(argv, log, rss_file, stderr=subprocess.STDOUT):
    # GNU time execs with a small image before forking the CLI: Python's inherited
    # high-water mark cannot become the CLI measurement. Never fall back to wait4.
    assert Path('/usr/bin/time').is_file(), 'GNU time is required on Ubuntu CI'
    proc = subprocess.Popen(['/usr/bin/time', '-f', '%M', '-o', str(rss_file),
                             '--', *argv], stdout=log, stderr=stderr,
                            start_new_session=True)
    try:
        code = proc.wait(timeout=180)
        return code, int(rss_file.read_text().strip())
    except BaseException:
        os.killpg(proc.pid, signal.SIGKILL)
        proc.wait()
        raise


def main(cycles=None, steady_rounds=100_000):
    build = subprocess.check_output(['cargo', 'build', '-p', 'irig106-time-cli',
        '--bin', 'irigtime', '--locked', '--message-format=json'], text=True)
    bins = [m['executable'] for line in build.splitlines()
            if (m := json.loads(line)).get('reason') == 'compiler-artifact'
            and m.get('executable') and m['target']['name'] == 'irigtime']
    assert len(bins) == 1, bins
    if cycles is None:
        cycles = (384*1024*1024 + CYCLE_BYTES-1)//CYCLE_BYTES
    with tempfile.TemporaryDirectory(prefix='irigtime-dense-rss-') as tmp:
        root = Path(tmp)
        # Bound peak fixture/report disk needs before writing; no committed file.
        assert shutil.disk_usage(root).free > max(cycles*(CYCLE_BYTES + 980*256), steady_rounds*40*(36+256))
        for label, writer, count in [('reset', write_workload, cycles),
                                      ('steady', write_steady_workload, steady_rounds)]:
            path = root/f'{label}.ch10'
            meta = writer(path, count)
            assert path.stat().st_size == meta['bytes']
            check_commands(bins[0], root, path, meta, label)
            check_json(bins[0], root, path, meta, label)
            if meta.get('steady'):
                check_large_timeline_json(bins[0], root, path, meta)
            path.unlink()


def log_contains(log, text):
    # Native spans can put summary/footer data beyond the diagnostic prefix.
    log.seek(0)
    return any(text in line for line in log)


def check_commands(binary, root, path, meta, label):
    for command in ['summary', 'channels', 'jumps', 'timeline', 'csv', 'correlate']:
        argv = [binary, command, str(path), '--fail-on', 'never']
        if command == 'timeline':
            argv += ['--limit', str(TIMELINE_LIMIT)]
        if command == 'csv':
            argv += ['--output', str(root/'report.csv')]
        if command == 'correlate':
            argv.insert(3, '2FAF080')  # RTC5s overlaps every segment.
        with (root/f'{command}.log').open('w+') as log:
            code, rss = measure(argv, log, root/'peak.txt')
            log.seek(0)
            prefix = log.read(8192)
            assert code == 0, (command, code, prefix)
            expected = 0 if meta.get('steady') else warnings_for(command, meta)
            if expected:
                assert log_contains(log, f'Findings: error=0, warning={expected}, info=0 (total={expected})'), (command, expected, prefix)
            else:
                assert not log_contains(log, 'Findings:'), (command, prefix)
            assert rss < 32*1024, (command, rss, 'exceeds 32MiB')
            if command == 'summary':
                assert f"Total Packets      : {meta['packets']:,}" in prefix
                if meta['jumps']:
                    assert log_contains(log, f"Total: {meta['jumps']} jump(s)")
                else:
                    assert log_contains(log, 'Time Jumps         : None detected')
                if meta.get('steady'):
                    assert all(log_contains(log, f'Channel {ch:>3}') for ch in range(7, 11))
            if command == 'timeline':
                log.seek(0)
                assert sum(1 for row in log if row.split() and row.split()[0].isdigit()) == TIMELINE_LIMIT
            if command == 'jumps' and meta.get('steady'):
                assert 'No time jumps detected across 4 channel(s).' in prefix
            if command == 'correlate' and meta.get('steady'):
                assert all(f'Channel {ch:>3}' in prefix for ch in range(7, 11))
            if command == 'correlate' and not meta.get('steady'):
                log.seek(0)
                assert sum('Channel   7 Segment' in row for row in log) == meta['segments']
        if command == 'csv':
            with (root/'report.csv').open('rb') as report:
                report.readline(1024)
                assert report.readline(1024).startswith(b'0,')
                report.seek(max(0, report.seek(0, 2)-1024))
                assert report.read(1024).splitlines()[-1].startswith(f"{meta['packets']-1},".encode())
            (root/'report.csv').unlink()
        result = (f"dense {label} {command}: {rss} KiB CLI peak (<32768); {meta['bytes']} bytes; "
                  f"{meta['packets']} packets / {meta['time_packets']} F1; "
                  f"{meta['resets']} resets / {meta['late']} late / {meta['jumps']} jumps")
        print(result, flush=True)
        if summary := os.environ.get('GITHUB_STEP_SUMMARY'):
            with open(summary, 'a') as out:
                out.write(result+'\n')


def check_json(binary, root, path, meta, label):
    for command in ['summary', 'channels', 'jumps', 'timeline', 'correlate']:
        with (root/'json.log').open('w+') as out, (root/'json.err').open('w+') as err:
            argv = [binary, command, str(path), '--format', 'json', '--fail-on', 'never']
            if command == 'timeline':
                argv += ['--limit', str(TIMELINE_LIMIT)]
            if command == 'correlate':
                argv.insert(3, '2FAF080')
            code, rss = measure(argv, out, root/'peak.txt', stderr=err)
            assert code == 0, (command, code)
            assert rss < 32*1024, (label, command, rss, 'JSON exceeds 32MiB')
            out.seek(0)
            # Only the harness loads the completed artifact. The measured CLI
            # streams its potentially long segment history from a private spool.
            value = json.load(out)
            report = value['report']
            if command == 'summary' and meta.get('steady'):
                quality = report['native_sessions']['spans'][0]['reference_quality']
                assert quality['pending_cap'] == '1024'
                assert quality['status'] == 'needs-context'
                assert quality['unavailable_reason'] == 'native quality pending cap (1024); prefix only'
                assert report['reference_count'] == '1024'

            assert report['total_packets'] == str(meta['packets'])
            assert report['time_packets'] == str(meta['time_packets'])
            expected = 0 if meta.get('steady') else warnings_for(command, meta)
            assert value['findings']['warning'] == str(expected)
            assert value['findings']['error'] == '0'
            if command == 'timeline':
                assert len(report['rows']) == TIMELINE_LIMIT
                assert value['options']['limit'] == str(TIMELINE_LIMIT)
            else:
                assert report['rows'] is None
                assert value['options']['limit'] is None
            if command == 'correlate':
                assert value['options']['query_rtc'] == '50000000'
                query = report['correlation']
                assert len(query['answers']) == (4 if meta.get('steady') else meta['segments'])
                assert (query['any']['clock'] is None) == (not meta.get('steady', False))
            else:
                assert value['options']['query_rtc'] is None
                assert report['correlation'] is None
            if command in ['channels', 'timeline', 'correlate']:
                assert report['jumps'] is None
                assert value['options']['threshold_ms'] is None
            else:
                assert report['jumps']['count'] == str(meta['jumps'])
            assert sum(len(c['segments']) for c in report['channels']) == (4 if meta.get('steady') else meta['segments'])
            assert len(report['channels']) == (4 if meta.get('steady') else 1)
        result = f'dense {label} {command} JSON: {rss} KiB CLI peak (<32768)'
        print(result, flush=True)
        if summary := os.environ.get('GITHUB_STEP_SUMMARY'):
            with open(summary, 'a') as out:
                out.write(result+'\n')


def check_large_timeline_json(binary, root, path, meta):
    # No retained JSON DOM in the CLI, even at a deliberately large caller cap.
    limit = 100_000
    with (root/'large-timeline.json').open('w+b') as out, (root/'large-timeline.err').open('w+') as err:
        code, rss = measure([binary, 'timeline', str(path), '--format', 'json',
                             '--limit', str(limit), '--fail-on', 'never'],
                            out, root/'peak.txt', stderr=err)
        assert code == 0, code
        assert rss < 32*1024, (rss, '100000 timeline rows exceed 32MiB')
        err.seek(0)
        assert not err.read(8192), 'steady workload must have no findings'
        out.seek(0)
        prefix = out.read(8192)
        assert b'"highest_level":null' in prefix
        assert f'"limit":"{limit}"'.encode() in prefix
        # The steady fixture has no finding samples: packet keys occur only in
        # rows. Count across chunk boundaries without loading the large artifact.
        out.seek(0)
        marker, carry, rows = b'"packet":', b'', 0
        while block := out.read(65536):
            chunk = carry + block
            rows += chunk.count(marker)
            carry = chunk[-(len(marker)-1):]
        assert rows == limit, rows
        out.seek(max(0, out.tell()-4096))
        tail = out.read(4096)
        assert f'"total_packets":"{meta["packets"]}"'.encode() in tail
        assert tail.endswith(b'}\n')
    result = f'dense steady timeline JSON limit {limit}: {rss} KiB CLI peak (<32768)'
    print(result, flush=True)
    if summary := os.environ.get('GITHUB_STEP_SUMMARY'):
        with open(summary, 'a') as out:
            out.write(result+'\n')


if __name__ == '__main__':
    main()
